public TFMPages pages()
{
    TFMPages pages = super();
    TFMPage page = pages.getPage('MoveSelectedLicensePlates');
    page.parmIcon(resourceStr(MobPalletMoveIcon));
    page.parmAvailableForMenuPages(false);
    return pages;
}

[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration MoveMultipleLicensePlatesActionFilter() 
{
    TFMReferenceDataConfiguration refData = new TFMReferenceDataConfiguration();
    TFMRegistrationCollectorList  warehouse = TFMGetReferenceData::createDefaultWarehouseReferenceData(1);
    refData.addCollector(warehouse);

    return refData;
}

[TFMCollectorMap(classStr(TFMGetRegistrationConfiguration), 'MoveSelectedLicensePlates')]
public Map MoveMultipleLicensePlatesPrompt()
{
    Map										returnMap = new Map(Types::String,Types::Class);
    TFMRegistrationCollectorText			Location = TFMRegistrationCollector::collectorFromEDT(extendedTypeStr(WMSLocationId));

    Location.parmId(20);
    returnMap.insert(extendedTypeStr(WMSLocationId),Location.getMap());

    return returnMap;
}

[TFMDocumentType(classStr(TFMPostAdhocRegistration),'MoveSelectedLicensePlates')]
public void MoveMultipleLicensePlatesPost()
{

    WMSLocationId		locId	= request.getFieldValue(extendedTypeStr(WMSLocationId));
    InventLocationId	whs		= request.getFieldValue(MobConstants::Warehouse());
    ClassName			context = 'getLPsToMove';
    SetEnumerator		lpList	= TFMMultiSelectionTable::GetAllInContext(curUserId(),context,request.parmdeviceID()).getEnumerator();
    WhsLicensePlateId	lpToMove;

    if (!WMSLocation::exist(locId,whs))
    {
        throw Error (strFmt("@SYS53781",locId,whs));
    }

    while(lpList.moveNext())
    {
        lpToMove = lpList.current();
        MobPostHelper::MoveLicensePlate(lpToMove,whs,locId);
        TFMMultiSelectionTable::addOrRemoveSelection(curUserId(),request.parmdeviceID(),lpToMove,context);
    }
}
